insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5839,"materia":"pen","nivel":1,"enunciado":"Romper o cadeado de uma bicicleta para levá-la caracteriza furto:","opcoes":["Qualificado, por rompimento de obstáculo","Simples, sem qualificadora, pois não houve violência","Privilegiado, pelo pequeno valor","De uso, se ele devolver depois"],"explicacao":"Art. 155, § 4º, I, do Código Penal."},{"id":5840,"materia":"pen","nivel":3,"enunciado":"O furto de veículo que é levado para outro estado ou para o exterior tem pena de:","opcoes":["Reclusão de 3 a 8 anos","Reclusão de 1 a 4 anos","Detenção de 6 meses a 2 anos","Reclusão de 12 a 30 anos"],"explicacao":"Art. 155, § 5º, do Código Penal."},{"id":5841,"materia":"pen","nivel":0,"enunciado":"Marcos vende a um comprador um carro que não é dele e some com o dinheiro. Ele comete:","opcoes":["Estelionato","Furto","Roubo","Receptação dolosa"],"explicacao":"Obteve vantagem enganando a vítima."},{"id":5842,"materia":"pen","nivel":1,"enunciado":"Matar alguém após uma discussão por causa de R$ 1 de troco é homicídio qualificado por motivo:","opcoes":["Fútil","Torpe","Nobre","De relevante valor social"],"explicacao":"Fútil é o motivo insignificante, desproporcional."},{"id":5843,"materia":"pen","nivel":3,"enunciado":"O pai que, logo após saber que a filha foi violentada, mata o agressor sob domínio de violenta emoção pode ter a pena:","opcoes":["Reduzida de 1/6 a 1/3 (homicídio privilegiado)","Aumentada de 1/3, por vingança","Extinta, por legítima defesa da honra da família","Dobrada, por ser crime hediondo"],"explicacao":"Art. 121, § 1º, do Código Penal."},{"id":5844,"materia":"pen","nivel":2,"enunciado":"O infanticídio só pode ser praticado:","opcoes":["Pela mãe, sob influência do estado puerperal","Por qualquer pessoa contra criança recém-nascida","Pelo pai, logo após o parto","Pelo médico que fez o parto"],"explicacao":"Art. 123 do Código Penal."},{"id":5845,"materia":"pen","nivel":1,"enunciado":"Para haver o crime de ameaça, o mal prometido deve ser:","opcoes":["Injusto e grave","Justo e leve","Necessariamente de morte","Escrito e assinado"],"explicacao":"Art. 147 do Código Penal."},{"id":5846,"materia":"pen","nivel":1,"enunciado":"Trancar a ex-companheira em casa por dias, impedindo-a de sair, é crime de:","opcoes":["Sequestro e cárcere privado","Constrangimento ilegal","Ameaça","Exercício arbitrário das próprias razões"],"explicacao":"Art. 148 do Código Penal, com pena maior se a vítima for companheira."},{"id":5847,"materia":"pen","nivel":1,"enunciado":"Durante uma blitz, o motorista apresenta uma CNH falsificada. Ele comete:","opcoes":["Uso de documento falso","Falsidade ideológica do documento","Estelionato","Desobediência"],"explicacao":"Art. 304 do Código Penal."},{"id":5848,"materia":"pen","nivel":3,"enunciado":"Dar nome de outra pessoa ao ser abordado, para esconder antecedentes, segundo a Súmula 522 do STJ:","opcoes":["É crime de falsa identidade, mesmo em autodefesa","Não é crime, por ser autodefesa garantida ao investigado","É apenas contravenção","É crime de uso de documento falso"],"explicacao":"Súmula 522 do STJ."},{"id":5849,"materia":"pen","nivel":4,"enunciado":"Pela Súmula 500 do STJ, o crime de corrupção de menores (praticar crime com adolescente):","opcoes":["É formal: não precisa provar que o menor foi corrompido","Exige prova da efetiva corrupção moral do menor envolvido","Só existe se o menor tiver menos de 14 anos","Foi revogado pelo ECA"],"explicacao":"Art. 244-B do ECA e Súmula 500 do STJ."},{"id":5850,"materia":"pen","nivel":3,"enunciado":"Tício atira para matar, erra todos os disparos e a vítima sai ilesa. Trata-se de tentativa:","opcoes":["Branca (incruenta)","Cruenta (vermelha)","Perfeita e consumada","Impossível"],"explicacao":"Na tentativa branca a vítima não é atingida."},{"id":5851,"materia":"pen","nivel":3,"enunciado":"Querendo matar Abel, Caim atira em Benedito, achando que era Abel. Caim responde:","opcoes":["Como se tivesse atingido Abel (erro sobre a pessoa)","Por homicídio culposo de Benedito, a vítima efetivamente atingida","Apenas por tentativa contra Abel","Por nenhum crime, por erro de tipo"],"explicacao":"Art. 20, § 3º, do Código Penal."},{"id":5852,"materia":"pen","nivel":4,"enunciado":"Por falha na pontaria, o agente atinge pessoa diversa da que queria atingir. Esse erro na execução chama-se:","opcoes":["Aberratio ictus","Aberratio criminis","Error in persona","Error in objecto"],"explicacao":"Art. 73 do Código Penal."},{"id":5853,"materia":"pen","nivel":0,"enunciado":"Uma pessoa vê alguém ferido numa calçada, poderia ajudar sem risco e vai embora sem chamar socorro. Ela comete:","opcoes":["Omissão de socorro","Lesão corporal","Abandono de incapaz","Nenhum crime"],"explicacao":"Art. 135 do Código Penal."},{"id":5854,"materia":"pen","nivel":2,"enunciado":"Obrigar um passageiro, sob ameaça, a descer do ônibus sem motivo legal é crime de:","opcoes":["Constrangimento ilegal","Sequestro e cárcere privado","Roubo","Desacato"],"explicacao":"Art. 146 do Código Penal."},{"id":5855,"materia":"ppen","nivel":1,"enunciado":"Alguém foi preso em flagrante às 22h de sábado. O auto de prisão deve chegar ao juiz:","opcoes":["Até as 22h de domingo","Até segunda-feira, no expediente","Em até 72 horas","Só quando terminar o inquérito"],"explicacao":"Art. 306, § 1º, do CPP: em até 24 horas."},{"id":5856,"materia":"ppen","nivel":1,"enunciado":"Com fundada suspeita de que alguém carrega uma arma, o policial revista sua mochila. Essa busca pessoal:","opcoes":["Dispensa mandado judicial","Exige mandado do juiz","Exige autorização do delegado","É proibida em via pública"],"explicacao":"Art. 244 do CPP."},{"id":5857,"materia":"ppen","nivel":1,"enunciado":"Pelo CPP, a busca pessoal em mulher deve ser feita:","opcoes":["Por outra mulher, se não atrasar ou prejudicar a diligência","Sempre por policial homem","Apenas na delegacia","Só com ordem judicial expressa e por policial do mesmo sexo ou não"],"explicacao":"Art. 249 do CPP."},{"id":5858,"materia":"ppen","nivel":2,"enunciado":"Preso em flagrante por crime com pena máxima de 6 anos, o suspeito pede fiança ao delegado. O delegado:","opcoes":["Não pode concedê-la; o pedido vai ao juiz","Pode concedê-la livremente, em qualquer valor que fixar","Deve soltá-lo sem fiança","Deve conceder fiança em dobro"],"explicacao":"O delegado só arbitra fiança se a pena máxima não passar de 4 anos (art. 322 do CPP)."},{"id":5859,"materia":"ppen","nivel":1,"enunciado":"Em crime de ação penal privada, o inquérito só pode começar:","opcoes":["A requerimento de quem pode oferecer a queixa","De ofício pelo delegado, assim que souber do fato","Por requisição da imprensa","Após a sentença"],"explicacao":"Art. 5º, § 5º, do CPP."},{"id":5860,"materia":"ppen","nivel":4,"enunciado":"Pela Lei 12.830/2013, o inquérito só pode ser avocado ou redistribuído:","opcoes":["Por despacho fundamentado do superior hierárquico","Por pedido do investigado","Por decisão da vítima","Por ordem verbal de qualquer autoridade policial ou judiciária"],"explicacao":"Art. 2º, § 4º, da Lei 12.830/2013."},{"id":5861,"materia":"ppen","nivel":1,"enunciado":"Uma confissão obtida por meio de tortura é:","opcoes":["Prova ilícita, que deve ser desentranhada do processo","Válida, se confirmada pela vítima em depoimento posterior","Válida, se o réu for reincidente","Prova plena da culpa"],"explicacao":"Art. 157 do CPP e art. 5º, LVI, da Constituição."},{"id":5862,"materia":"ppen","nivel":4,"enunciado":"A prova derivada de uma ilícita pode ser admitida quando:","opcoes":["Puder ser obtida por uma fonte independente","O crime for hediondo ou equiparado a hediondo","O juiz quiser","O réu for reincidente"],"explicacao":"Art. 157, §§ 1º e 2º, do CPP."},{"id":5863,"materia":"ppen","nivel":2,"enunciado":"Em crime permanente, como guardar droga em casa para venda, o flagrante:","opcoes":["É possível enquanto durar a permanência","Só é possível no primeiro dia em que a droga foi guardada","Nunca é possível","Depende de mandado judicial"],"explicacao":"Art. 303 do CPP."},{"id":5864,"materia":"ppen","nivel":3,"enunciado":"Pelo CPP, NÃO se defere compromisso de dizer a verdade à testemunha:","opcoes":["Menor de 14 anos","Maior de 60 anos","Policial militar","Vizinha da vítima"],"explicacao":"Art. 208 do CPP: também doentes mentais e parentes próximos do acusado."},{"id":5865,"materia":"leg","nivel":3,"enunciado":"Pelo ECA, a internação de adolescente deve ser reavaliada, no máximo, a cada:","opcoes":["6 meses","1 mês","2 anos","3 anos"],"explicacao":"Art. 121, § 2º, do ECA."},{"id":5866,"materia":"leg","nivel":3,"enunciado":"Pela Lei de Abuso de Autoridade, prosseguir no interrogatório de quem decidiu ficar calado é:","opcoes":["Crime","Permitido, se for flagrante","Permitido, se o crime for grave","Apenas descortesia"],"explicacao":"Art. 15, parágrafo único, I, da Lei 13.869/2019."},{"id":5867,"materia":"leg","nivel":0,"enunciado":"Impedir uma pessoa de entrar em um restaurante por causa da cor da pele é:","opcoes":["Crime de racismo","Apenas falta de educação","Contravenção penal","Infração de trânsito"],"explicacao":"Lei 7.716/1989."},{"id":5868,"materia":"leg","nivel":2,"enunciado":"Reter o cartão bancário de um idoso para receber uma dívida é, pelo Estatuto da Pessoa Idosa:","opcoes":["Crime","Permitido, se a dívida existir","Infração só administrativa","Exercício regular de direito"],"explicacao":"Art. 104 da Lei 10.741/2003."},{"id":5869,"materia":"leg","nivel":0,"enunciado":"Qual destes crimes é hediondo?","opcoes":["Latrocínio","Furto simples","Ameaça","Lesão corporal leve"],"explicacao":"Lei 8.072/1990: o roubo seguido de morte é hediondo."},{"id":5870,"materia":"const","nivel":1,"enunciado":"Um grupo quer fazer uma manifestação pacífica, sem armas, numa praça. Pela Constituição, ele precisa:","opcoes":["Apenas avisar a autoridade antes","Pedir autorização ao juiz","Pedir autorização ao prefeito","Pagar uma taxa ao Estado"],"explicacao":"Art. 5º, XVI, da Constituição."},{"id":5871,"materia":"const","nivel":2,"enunciado":"Se o MP não oferece a denúncia no prazo legal, a vítima pode propor:","opcoes":["Ação penal privada subsidiária da pública","Mandado de injunção contra a omissão do promotor","Ação popular","Habeas data"],"explicacao":"Art. 5º, LIX, da Constituição."},{"id":5872,"materia":"const","nivel":1,"enunciado":"Pela Constituição, criar um tribunal só para julgar um crime que já aconteceu é:","opcoes":["Proibido: não haverá juízo ou tribunal de exceção","Permitido em casos graves","Permitido pelo Congresso, por lei aprovada depois do crime","Permitido com o aval do STF"],"explicacao":"Art. 5º, XXXVII, da Constituição."},{"id":5873,"materia":"const","nivel":0,"enunciado":"Pela Constituição, o Estado prestará assistência jurídica integral e gratuita:","opcoes":["Aos que comprovarem insuficiência de recursos","A todos, sem exceção","Só a servidores públicos e a seus dependentes","Só a estrangeiros"],"explicacao":"Art. 5º, LXXIV. Quem presta é a Defensoria Pública."},{"id":5874,"materia":"const","nivel":1,"enunciado":"Pela Constituição, o condenado por erro judiciário:","opcoes":["Será indenizado pelo Estado","Não tem direito a nada","Deve processar o juiz pessoalmente","Só recebe desculpas oficiais"],"explicacao":"Art. 5º, LXXV. Também quem ficar preso além do tempo da sentença."},{"id":5875,"materia":"const","nivel":1,"enunciado":"Pela Constituição, às presidiárias é assegurado:","opcoes":["Condições para ficar com os filhos durante a amamentação","Prisão domiciliar sempre","Redução automática da pena","Cumprimento da pena em casa, junto com toda a família"],"explicacao":"Art. 5º, L, da Constituição."},{"id":5876,"materia":"const","nivel":2,"enunciado":"O juiz natural, garantido na Constituição, significa que ninguém será processado nem sentenciado:","opcoes":["Senão pela autoridade competente","Sem confessar","Sem testemunha ocular","Fora da cidade onde mora ou onde ocorreu o crime"],"explicacao":"Art. 5º, LIII, da Constituição."},{"id":5877,"materia":"adm","nivel":2,"enunciado":"Um chefe transfere um servidor para outra cidade só para se vingar dele. Isso é abuso de poder na forma de:","opcoes":["Desvio de finalidade","Excesso de poder","Poder vinculado","Autotutela"],"explicacao":"O ato tinha competência, mas fim diverso do interesse público."},{"id":5878,"materia":"adm","nivel":2,"enunciado":"O fiscal aplica uma multa maior do que a lei permite. Isso é abuso de poder na forma de:","opcoes":["Excesso de poder","Desvio de finalidade","Poder discricionário","Delegação"],"explicacao":"O agente foi além dos limites de sua competência."},{"id":5879,"materia":"adm","nivel":1,"enunciado":"O decreto do Presidente que detalha como uma lei será cumprida é exercício do poder:","opcoes":["Regulamentar","Disciplinar","De polícia","Hierárquico"],"explicacao":"Art. 84, IV, da Constituição."},{"id":5880,"materia":"adm","nivel":2,"enunciado":"A Administração concede aposentadoria a quem cumpriu todos os requisitos legais. Esse ato é:","opcoes":["Vinculado","Discricionário","Político","Inexistente"],"explicacao":"Preenchidos os requisitos, não há escolha."},{"id":5881,"materia":"adm","nivel":1,"enunciado":"Criar uma nova secretaria dentro da própria prefeitura é exemplo de:","opcoes":["Desconcentração","Descentralização","Privatização","Concessão"],"explicacao":"Na desconcentração, a divisão ocorre dentro da mesma pessoa jurídica."},{"id":5882,"materia":"adm","nivel":0,"enunciado":"O princípio que impede a interrupção de serviços essenciais, como a segurança pública, é o da:","opcoes":["Continuidade do serviço público","Autotutela","Especialidade","Publicidade"],"explicacao":"Os serviços públicos não podem parar."},{"id":5883,"materia":"adm","nivel":1,"enunciado":"Pela Lei 8.112/1990, pelo mesmo fato, o servidor pode responder:","opcoes":["Civil, penal e administrativamente, de forma independente","Só administrativamente","Só na esfera penal","Apenas na esfera que escolher, pois uma exclui as outras"],"explicacao":"Art. 125 da Lei 8.112/1990."},{"id":5884,"materia":"port","nivel":0,"enunciado":"Complete: “Estudou muito, ___ não passou.”","opcoes":["mas","mais","mal","mau"],"explicacao":"“Mas” indica oposição; “mais” indica quantidade."},{"id":5885,"materia":"port","nivel":1,"enunciado":"Complete: “___ você vai com essa viatura?”","opcoes":["Aonde","Onde","Donde","Adonde"],"explicacao":"Com verbo de movimento (ir a), usa-se “aonde”."},{"id":5886,"materia":"port","nivel":1,"enunciado":"Complete: “O depoimento ficou para ___ analisar.”","opcoes":["eu","mim","me","comigo"],"explicacao":"Antes de verbo no infinitivo, o sujeito é “eu”: para eu analisar."},{"id":5887,"materia":"port","nivel":3,"enunciado":"Em “Os policiais chegaram cedo, a fim de render a equipe”, “a fim de” indica:","opcoes":["Finalidade","Causa","Tempo","Comparação"],"explicacao":"“Afim” (junto) significa semelhante; “a fim de”, para."},{"id":5888,"materia":"inf","nivel":1,"enunciado":"A verificação em duas etapas (2FA) serve para:","opcoes":["Exigir uma segunda prova de identidade além da senha","Deixar a internet mais rápida","Apagar vírus do computador","Fazer backup automático dos arquivos na nuvem do navegador"],"explicacao":"Ex.: código no celular além da senha."},{"id":5889,"materia":"inf","nivel":2,"enunciado":"No Excel, a fórmula =CONT.SE(A1:A10;\"furto\") retorna:","opcoes":["Quantas células do intervalo contêm “furto”","A soma dos números das células ao lado de “furto”","A primeira célula com “furto”","Um erro, pois texto não pode ser contado"],"explicacao":"CONT.SE conta as células que atendem a um critério."},{"id":5890,"materia":"inf","nivel":1,"enunciado":"Guardar arquivos em servidores na internet para acessá-los de qualquer lugar é usar:","opcoes":["Armazenamento em nuvem","Memória RAM","Pen drive","Disco local"],"explicacao":"Ex.: Google Drive, OneDrive."},{"id":5891,"materia":"rl","nivel":0,"enunciado":"Em uma delegacia, 20% dos 50 inquéritos foram concluídos. Quantos foram concluídos?","opcoes":["10","20","5","25"],"explicacao":"20% de 50 = 10."},{"id":5892,"materia":"rl","nivel":1,"enunciado":"Se 3 viaturas gastam 60 litros de combustível em um dia, 5 viaturas gastam:","opcoes":["100 litros","80 litros","120 litros","90 litros"],"explicacao":"Regra de três: 60 ÷ 3 = 20 por viatura; 20 × 5 = 100."},{"id":5893,"materia":"rl","nivel":2,"enunciado":"A proposição “Se é policial, então é servidor” equivale a:","opcoes":["Se não é servidor, então não é policial","Se é servidor público, então é policial","Se não é policial, então não é servidor","É policial e não é servidor"],"explicacao":"É a contrapositiva: troca e nega os termos."},{"id":5894,"materia":"rl","nivel":3,"enunciado":"Dois suspeitos são interrogados. Um sempre mente e o outro sempre fala a verdade. Rui diz: “Eu minto”. Essa afirmação:","opcoes":["Não pode ter sido dita por nenhum dos dois","Prova que Rui é o mentiroso do par","Prova que Rui é sincero","Prova que os dois mentem"],"explicacao":"Se Rui fosse sincero, mentiria; se mentisse, diria a verdade. Contradição."},{"id":5895,"materia":"dh","nivel":2,"enunciado":"Pelos princípios da ONU sobre uso da força, o policial deve usar arma de fogo:","opcoes":["Só como último recurso, para proteger a vida","Sempre que o suspeito correr ou não parar na abordagem","Para assustar a multidão","Sempre que for desobedecido"],"explicacao":"Princípios da legalidade, necessidade e proporcionalidade."},{"id":5896,"materia":"dh","nivel":0,"enunciado":"Pela Declaração Universal dos Direitos Humanos, toda pessoa acusada tem direito a ser presumida:","opcoes":["Inocente até que se prove sua culpa","Culpada até que ela mesma prove a sua inocência","Culpada se for reincidente","Inocente só se for primária"],"explicacao":"Artigo 11 da Declaração."},{"id":5897,"materia":"ml","nivel":3,"enunciado":"Marcas de unhas no pescoço da vítima são típicas de:","opcoes":["Esganadura","Enforcamento","Afogamento","Soterramento"],"explicacao":"Na esganadura, a constrição é feita com as mãos."},{"id":5898,"materia":"pcd","nivel":0,"enunciado":"Pela Lei Brasileira de Inclusão, discriminar pessoa por causa de sua deficiência é:","opcoes":["Crime","Apenas falta de educação","Permitido no comércio","Infração só administrativa"],"explicacao":"Art. 88 da Lei 13.146/2015."},{"id":5899,"materia":"ia","nivel":1,"enunciado":"Um vídeo falso, gerado por inteligência artificial, que imita o rosto e a voz de uma pessoa real é chamado de:","opcoes":["Deepfake","Firewall","Backup","Spam"],"explicacao":"Pode ser usado em golpes e desinformação."},{"id":5900,"materia":"cont","nivel":1,"enunciado":"Pela LGPD, o dado sobre a origem racial, a religião ou a saúde de alguém é chamado de dado:","opcoes":["Sensível","Público","Anônimo","Comercial"],"explicacao":"Art. 5º, II, da Lei 13.709/2018."},{"id":5901,"materia":"pen","nivel":2,"enunciado":"O credor que entra na casa do devedor e leva a TV dele para se pagar, sem ordem judicial, comete:","opcoes":["Exercício arbitrário das próprias razões","Furto qualificado","Roubo","Nenhum crime, pois a dívida existe e estava vencida"],"explicacao":"Art. 345 do Código Penal: fazer justiça pelas próprias mãos."},{"id":5902,"materia":"pen","nivel":2,"enunciado":"Esconder em casa um amigo procurado pela polícia por crime com reclusão, para que ele não seja preso, é:","opcoes":["Favorecimento pessoal","Favorecimento real","Receptação","Associação criminosa armada"],"explicacao":"Art. 348 do Código Penal. O favorecimento real protege o proveito do crime."},{"id":5903,"materia":"pen","nivel":3,"enunciado":"No favorecimento pessoal, se quem ajuda o criminoso é seu pai, filho, cônjuge ou irmão:","opcoes":["Fica isento de pena","Tem a pena dobrada","Responde como coautor","Responde por associação criminosa"],"explicacao":"Art. 348, § 2º, do Código Penal."},{"id":5904,"materia":"pen","nivel":2,"enunciado":"Limpar o sangue e mudar o corpo de lugar para enganar a perícia é crime de:","opcoes":["Fraude processual","Falso testemunho","Desobediência","Favorecimento real"],"explicacao":"Art. 347 do Código Penal; a pena dobra se for processo penal."},{"id":5905,"materia":"pen","nivel":2,"enunciado":"Ameaçar uma testemunha para que ela não deponha contra o réu é:","opcoes":["Coação no curso do processo","Constrangimento ilegal simples","Falso testemunho","Prevaricação"],"explicacao":"Art. 344 do Código Penal."},{"id":5906,"materia":"pen","nivel":0,"enunciado":"Chamar o vizinho de “burro e vagabundo” na frente de outras pessoas é crime de:","opcoes":["Injúria","Calúnia","Difamação","Ameaça"],"explicacao":"Injúria ofende a dignidade, sem atribuir um fato."},{"id":5907,"materia":"pen","nivel":1,"enunciado":"Espalhar no trabalho que uma colega chega bêbada todos os dias, para manchar sua reputação, é:","opcoes":["Difamação","Calúnia","Injúria","Ameaça"],"explicacao":"Difamação atribui um fato ofensivo que não é crime."},{"id":5908,"materia":"pen","nivel":1,"enunciado":"Seguir alguém repetidamente, ameaçando sua integridade e invadindo sua privacidade, é o crime de:","opcoes":["Perseguição (stalking)","Rixa","Ameaça simples, repetida várias vezes","Constrangimento ilegal"],"explicacao":"Art. 147-A do Código Penal, incluído em 2021."},{"id":5909,"materia":"pen","nivel":2,"enunciado":"Invadir o celular de outra pessoa para obter seus dados sem autorização é:","opcoes":["Crime de invasão de dispositivo informático","Apenas infração civil, resolvida com indenização","Furto simples","Estelionato"],"explicacao":"Art. 154-A do Código Penal."},{"id":5910,"materia":"pen","nivel":3,"enunciado":"Um jovem pratica um crime às 10h do dia em que completa 18 anos. Ele é:","opcoes":["Imputável, pois já tem 18 anos","Inimputável até o dia seguinte","Inimputável até completar 21","Imputável só para crimes graves"],"explicacao":"A maioridade penal começa no primeiro minuto do aniversário."},{"id":5911,"materia":"pen","nivel":4,"enunciado":"Exigir tributo que sabe ser indevido, ou cobrá-lo por meio vexatório, é:","opcoes":["Excesso de exação","Concussão simples","Peculato","Corrupção passiva"],"explicacao":"Art. 316, § 1º, do Código Penal."},{"id":5912,"materia":"pen","nivel":3,"enunciado":"O servidor que revela a terceiros um fato sigiloso que conheceu em razão do cargo comete:","opcoes":["Violação de sigilo funcional","Prevaricação","Condescendência criminosa, por ter sido tolerante","Advocacia administrativa"],"explicacao":"Art. 325 do Código Penal."},{"id":5913,"materia":"pen","nivel":1,"enunciado":"Deixar uma criança pequena sozinha em casa por dias, expondo-a a perigo, é:","opcoes":["Abandono de incapaz","Maus-tratos a animal","Omissão de socorro","Lesão corporal"],"explicacao":"Art. 133 do Código Penal."},{"id":5914,"materia":"ppen","nivel":3,"enunciado":"Se os vestígios do crime desapareceram, a falta do exame de corpo de delito pode ser suprida por:","opcoes":["Prova testemunhal","Confissão do acusado","Denúncia anônima","Nada; o processo é nulo"],"explicacao":"Art. 167 do CPP. A confissão não supre o exame (art. 158)."},{"id":5915,"materia":"ppen","nivel":3,"enunciado":"O juiz verifica que o preso em flagrante agiu em legítima defesa. Ele pode:","opcoes":["Conceder liberdade provisória","Decretar a preventiva obrigatoriamente","Condená-lo na audiência","Mandá-lo ao júri imediatamente"],"explicacao":"Art. 310, § 1º, do CPP."},{"id":5916,"materia":"ppen","nivel":3,"enunciado":"O interrogatório é dividido em duas partes:","opcoes":["Sobre a pessoa do acusado e sobre os fatos","Sobre a vítima e sobre as testemunhas de acusação","Sobre a pena e sobre a fiança","Sobre a perícia e sobre a sentença"],"explicacao":"Art. 187 do CPP."},{"id":5917,"materia":"ppen","nivel":4,"enunciado":"No Juizado Especial Criminal, se o autor não for encontrado para ser citado pessoalmente:","opcoes":["O caso é remetido ao juízo comum","Ele é citado por edital no Juizado","O processo é arquivado","Ele é julgado à revelia"],"explicacao":"Art. 66, parágrafo único, da Lei 9.099/1995."},{"id":5918,"materia":"leg","nivel":1,"enunciado":"Pichar o muro de uma escola é crime previsto na:","opcoes":["Lei de Crimes Ambientais","Lei de Drogas","Lei Maria da Penha","Lei de Tortura"],"explicacao":"Art. 65 da Lei 9.605/1998."},{"id":5919,"materia":"leg","nivel":1,"enunciado":"O programa “Sinal Vermelho”, em que a vítima mostra um X na mão em farmácias, combate:","opcoes":["A violência doméstica contra a mulher","O tráfico de drogas","O trabalho infantil em comércios e farmácias","Os golpes bancários"],"explicacao":"Lei 14.188/2021."},{"id":5920,"materia":"leg","nivel":2,"enunciado":"Guardar munição em casa sem autorização, pelo Estatuto do Desarmamento, é:","opcoes":["Crime de posse irregular","Permitido sem a arma","Apenas infração administrativa","Contravenção"],"explicacao":"Art. 12 da Lei 10.826/2003 inclui acessório e munição."},{"id":5921,"materia":"const","nivel":2,"enunciado":"Pela Constituição, as Forças Armadas destinam-se à defesa da Pátria, à garantia dos poderes constitucionais e:","opcoes":["Da lei e da ordem, por iniciativa de qualquer dos Poderes","Da arrecadação de impostos","Da investigação de crimes comuns, no lugar da Polícia Civil","Do julgamento de civis"],"explicacao":"Art. 142 da Constituição."},{"id":5922,"materia":"const","nivel":4,"enunciado":"Pela Constituição, a segurança viária, exercida para a preservação da ordem pública e da incolumidade das pessoas nas vias, compete:","opcoes":["Aos órgãos ou entidades executivos e seus agentes de trânsito","Somente à Polícia Federal","Somente às Forças Armadas, em cooperação com a Polícia Federal","Ao Ministério Público"],"explicacao":"Art. 144, § 10, incluído pela EC 82/2014."},{"id":5923,"materia":"adm","nivel":3,"enunciado":"Pela teoria do órgão, quando o policial age em serviço, sua atuação é atribuída:","opcoes":["Ao Estado","Somente a ele, pessoalmente","Ao sindicato da categoria","A ninguém"],"explicacao":"Teoria da imputação volitiva, de Otto Gierke."},{"id":5924,"materia":"adm","nivel":3,"enunciado":"Um ato com vício de competência não exclusiva pode ser:","opcoes":["Convalidado pela autoridade competente","Apenas revogado","Nunca corrigido","Corrigido só pelo Judiciário, a pedido do interessado"],"explicacao":"Art. 55 da Lei 9.784/1999."},{"id":5925,"materia":"port","nivel":1,"enunciado":"“O juiz ___ a decisão, confirmando-a.” Complete corretamente:","opcoes":["ratificou","retificou","retirou","ratificaram"],"explicacao":"Ratificar é confirmar; retificar é corrigir."},{"id":5926,"materia":"port","nivel":1,"enunciado":"Qual frase está correta?","opcoes":["Eles têm o direito de ficar calados.","Eles tem o direito de ficar calados.","Ele têm o direito de ficar calado.","Eles teem o direito de ficar calados."],"explicacao":"No plural, “têm” leva acento circunflexo."},{"id":5927,"materia":"port","nivel":1,"enunciado":"Em “Delegado, venha até a sala”, a vírgula isola:","opcoes":["Um vocativo","Um aposto","Um adjunto adverbial","O sujeito"],"explicacao":"Vocativo é o chamamento."},{"id":5928,"materia":"port","nivel":0,"enunciado":"O antônimo de “absolver” é:","opcoes":["Condenar","Perdoar","Inocentar","Liberar"],"explicacao":"Absolver é declarar inocente."},{"id":5929,"materia":"port","nivel":2,"enunciado":"“O juiz ___ uma pena severa ao réu, que ___ a lei.” Complete:","opcoes":["infligiu / infringiu","infringiu / infligiu","infligiu / infligiu","infringiu / infringiu"],"explicacao":"Infligir é aplicar pena; infringir é violar."},{"id":5930,"materia":"port","nivel":2,"enunciado":"Qual frase usa corretamente “descriminar”?","opcoes":["Querem descriminar o uso de certas drogas.","É crime descriminar alguém pela cor.","Não se deve descriminar os pobres.","A lei proíbe descriminar mulheres."],"explicacao":"Descriminar é deixar de considerar crime; discriminar é tratar com preconceito."},{"id":5931,"materia":"inf","nivel":0,"enunciado":"No navegador, o atalho Ctrl + P serve para:","opcoes":["Imprimir","Pesquisar","Colar","Abrir nova aba"],"explicacao":"P de “print”."},{"id":5932,"materia":"inf","nivel":1,"enunciado":"No e-mail, quem está em “Cco” (cópia oculta):","opcoes":["Recebe a mensagem, mas os outros não veem seu endereço","Não recebe a mensagem, só uma notificação de que ela foi enviada","Vê apenas o assunto","Recebe só os anexos"],"explicacao":"Cco esconde o destinatário dos demais."},{"id":5933,"materia":"rl","nivel":2,"enunciado":"Quantos anagramas tem a palavra PAZ?","opcoes":["6","3","9","4"],"explicacao":"3! = 3 × 2 × 1 = 6."},{"id":5934,"materia":"rl","nivel":0,"enunciado":"Uma farda custa R$ 200,00 e tem desconto de 10%. Quanto se paga?","opcoes":["R$ 180,00","R$ 190,00","R$ 120,00","R$ 100,00"],"explicacao":"10% de 200 = 20; 200 - 20 = 180."},{"id":5935,"materia":"rl","nivel":3,"enunciado":"Um policial trabalha 12 horas e folga 36 horas. Se começou um plantão às 7h de segunda, o próximo plantão começa:","opcoes":["Às 7h de quarta-feira","Às 19h de segunda-feira","Às 7h de terça-feira","Às 19h de terça-feira"],"explicacao":"Sai às 19h de segunda; +36 h = 7h de quarta."},{"id":5936,"materia":"ml","nivel":3,"enunciado":"A mumificação e a saponificação são fenômenos cadavéricos:","opcoes":["Conservadores","Destrutivos","Abióticos imediatos","Vitais"],"explicacao":"Preservam o corpo, ao contrário da putrefação."},{"id":5937,"materia":"ia","nivel":1,"enunciado":"Quando uma IA inventa uma informação falsa e a apresenta como verdadeira, chama-se:","opcoes":["Alucinação","Criptografia","Compilação","Indexação"],"explicacao":"Por isso, as respostas da IA devem ser conferidas."},{"id":5938,"materia":"cont","nivel":1,"enunciado":"Pela LGPD, a pessoa natural a quem se referem os dados pessoais é o:","opcoes":["Titular","Controlador","Operador","Encarregado"],"explicacao":"Art. 5º, V, da Lei 13.709/2018."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
